{
  "status": "SUPPORTED",
  "task_summary": "Find fastening parts and tool in storage, fasten component at marked spot on workbench, leave tool on workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "workbench_surface",
        "entity_kind": "REGION",
        "function": "Surface where fastening occurs and tools are left.",
        "required_count": 1,
        "binding_policy": "SHARED"
      ,
        "candidate_categories": ["wooden desk"],
        "required_properties": ["stable", "horizontal"]
      },
      {
        "id": "fastening_target",
        "entity_kind": "FIXED_TARGET",
        "function": "Specific spot on workbench to be fastened.",
        "required_count": 1,
        "binding_policy": "DISTINCT"
      ,
        "candidate_categories": ["marked location", "hole", "mount point"],
        "required_properties": ["accessible"]
      },
      {
        "id": "fastener_tool",
        "entity_kind": "OBJECT",
        "function": "Implement used to secure the component.",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      ,
        "candidate_categories": ["screwdriver", "drill", "wrench"],
        "required_properties": ["functional", "portable"]
      },
      {
        "id": "fastening_component",
        "entity_kind": "OBJECT",
        "function": "Hardware part to be fastened.",
        "required_count": 1,
        "binding_policy": "DISTINCT"
      ,
        "candidate_categories": ["screw", "bolt", "bracket", "nut"],
        "required_properties": ["compatible", "small"]
      },
      {
        "id": "storage_container",
        "entity_kind": "REGION",
        "function": "Closed storage area to search for components.",
        "required_count": 2,
        "binding_policy": "DISTINCT"
      ,
        "candidate_categories": ["drawer", "cabinet", "box"],
        "required_properties": ["closed", "openable"]
      }
    ],
    "functional_relations": [
      {
        "id": "secures_to",
        "relation": "fastener_tool secures fastening_component at fastening_target",
        "participant_roles": ["fastener_tool", "fastening_component", "fastening_target"]
      ,
        "required": true
      },
      {
        "id": "left_on",
        "relation": "fastener_tool is left on workbench_surface",
        "participant_roles": ["fastener_tool", "workbench_surface"]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "search_and_retrieve",
        "operation": "Search storage containers and retrieve fastener_tool and fastening_component",
        "participant_roles": ["storage_container", "fastener_tool", "fastening_component"],
        "operation_count": 1
      },
      {
        "id": "perform_fastening",
        "operation": "Use fastener_tool to fasten fastening_component at fastening_target",
        "participant_roles": ["fastener_tool", "fastening_component", "fastening_target"],
        "operation_count": 1
      },
      {
        "id": "deposit_tool",
        "operation": "Place fastener_tool on workbench_surface",
        "participant_roles": ["fastener_tool", "workbench_surface"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "workbench_surface": [
        {
          "label": "wooden desk",
          "visual_description": "Brown wooden table with drawers underneath and a grey cabinet behind."
        }
      ],
      "fastening_target": [
        {
          "label": "desk surface",
          "visual_description": "Top of the wooden desk where the yellow object rests."
        }
      ],
      "fastener_tool": [
        {
          "label": "yellow object",
          "visual_description": "Yellow rectangular item on a black tray on the desk."
        },
        {
          "label": "potential tool",
          "visual_description": "Contents of the grey cabinet or blue drawers."
        }
      ],
      "fastening_component": [
        {
          "label": "hidden component",
          "visual_description": "Likely inside the blue drawers or grey cabinet."
        }
      ],
      "storage_container": [
        {
          "label": "blue drawers",
          "visual_description": "Two blue drawers under the desk handles facing forward."
        },
        {
          "label": "grey cabinet",
          "visual_description": "Tall grey metal cabinet standing behind the desk."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "storage_container",
        "label": "blue drawers",
        "visual_description": "Closed blue drawers under desk.",
        "reason": "Standard storage location for small hardware and tools."
      },
      {
        "id": "storage_container",
        "label": "grey cabinet",
        "visual_description": "Closed grey cabinet behind desk.",
        "reason": "Enclosed storage likely containing larger tools or components."
      }
    ],
    "inspection_order": [
      "blue drawers",
      "grey cabinet"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
